sp_widget.css:
/* =========================================================
   GATENOW LANDING · FAQ
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   Design notes worth keeping:

   1. Three columns by two rows. Three earlier versions stacked
      the questions and every one of them ran long, because six
      questions in a column is six questions tall whatever the
      styling. Across the width, the same content is about one
      screen.

   2. Cells are separated by hairlines, not boxes. The page
      already uses panels for About and a sheet for the process,
      so this reads as a printed column of questions rather than
      six more cards.

   3. The wash on hover rises from the bottom of the cell and
      the accent rule draws across the top, so a hovered cell is
      framed by the two movements rather than simply tinted.

   4. Nothing is held at opacity zero in a base rule. The
      from-state comes from animation-fill-mode backwards, so if
      animation is blocked the content still renders.
   ========================================================= */

/* ---------- typeface ----------
   Shared with the other landing widgets. If they sit on one
   page, keep a single copy in a Style Sheet record attached to
   the theme and delete this block from the widgets.
   ------------------------------------------------------------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- palette ---------- */
$gnf-navy:      #0a2540;
$gnf-blue:      #1560e0;
$gnf-blue-dk:   #0f4cbb;
$gnf-blue-soft: #eef3fd;
$gnf-body:      #55677f;
$gnf-hair:      #dfe7f3;
$gnf-white:     #ffffff;

$gnf-ease:      cubic-bezier(0.45, 0.05, 0.25, 1);

$gnf-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   BAND
   ========================================================= */

.gnf-faq {
  position: relative;
  width: 100%;
  padding: 100px 24px 108px;
  font-family: $gnf-font;
  color: $gnf-navy;
  background: linear-gradient(180deg, #eef4fd 0%, #f6fafe 56%, #ffffff 100%);
}

.gnf-faq *,
.gnf-faq *::before,
.gnf-faq *::after { box-sizing: border-box; }

.gnf-faq__inner {
  position: relative;
  max-width: 1140px;
  margin: 0 auto;
}


/* =========================================================
   HEADER
   ========================================================= */

.gnf-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 420px);
  align-items: end;
  gap: 20px 56px;
  margin-bottom: 44px;
}

.gnf-head__lead { min-width: 0; }
.gnf-head__aside { min-width: 0; }

.gnf-faq .gnf-eyebrow {
  display: inline-flex;
  align-items: center;
  padding: 8px 18px;
  margin: 0 0 22px;
  border-radius: 999px;
  background: $gnf-blue-soft;
  color: $gnf-blue;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.gnf-faq .gnf-heading {
  margin: 0;
  max-width: 520px;
  font-size: 46px;
  font-weight: 700;
  line-height: 1.13;
  letter-spacing: -0.032em;
  color: $gnf-navy;
}

@supports (font-size: clamp(30px, 3.6vw, 46px)) {
  .gnf-faq .gnf-heading { font-size: clamp(30px, 3.6vw, 46px); }
}

.gnf-faq .gnf-sub {
  margin: 0;
  padding: 0 0 0 22px;
  border-left: 2px solid rgba(21, 96, 224, 0.22);
  font-size: 16.5px;
  font-weight: 400;
  line-height: 1.64;
  color: $gnf-body;
}

.gnf-headlink {
  position: relative;
  display: inline-flex;
  align-items: center;
  margin: 14px 0 0 22px;
  padding: 2px 0 5px;
  color: $gnf-blue;
  font-size: 15px;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.55s $gnf-ease;
}

.gnf-headlink:hover,
.gnf-headlink:focus {
  color: $gnf-blue-dk;
  text-decoration: none;
}

.gnf-headlink__rule {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.55s $gnf-ease;
}

.gnf-headlink:hover .gnf-headlink__rule,
.gnf-headlink:focus .gnf-headlink__rule { transform: scaleX(1); }


/* =========================================================
   GRID
   Hairlines between cells rather than a border around each, so
   the block reads as one field of questions.
   ========================================================= */

.gnf-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid $gnf-hair;
  border-bottom: 1px solid $gnf-hair;
}

.gnf-cell {
  position: relative;
  padding: 34px 32px 36px;
  overflow: hidden;
}

/* vertical rules between columns only */
.gnf-cell--2,
.gnf-cell--3,
.gnf-cell--5,
.gnf-cell--6 { border-left: 1px solid $gnf-hair; }

/* horizontal rule between the two rows */
.gnf-cell--4,
.gnf-cell--5,
.gnf-cell--6 { border-top: 1px solid $gnf-hair; }

/* the wash rises from the foot of the cell */
.gnf-cell__wash {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background: linear-gradient(0deg, rgba(21, 96, 224, 0.09) 0%, rgba(21, 96, 224, 0) 72%);
  transform: scaleY(0);
  transform-origin: center bottom;
  transition: transform 0.6s $gnf-ease;
  pointer-events: none;
}

/* the rule draws across the head of it */
.gnf-cell__accent {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  background: linear-gradient(90deg, $gnf-blue 0%, rgba(21, 96, 224, 0.25) 100%);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.6s $gnf-ease;
  pointer-events: none;
}

.gnf-cell:hover .gnf-cell__wash { transform: scaleY(1); }
.gnf-cell:hover .gnf-cell__accent { transform: scaleX(1); }

.gnf-cell__body {
  position: relative;
  z-index: 2;
}

.gnf-cell__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.gnf-cell__num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 24px;
  border-radius: 7px;
  background: rgba(21, 96, 224, 0.1);
  color: $gnf-blue;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  transition: background 0.55s $gnf-ease, color 0.55s $gnf-ease;
}

.gnf-cell:hover .gnf-cell__num {
  background: $gnf-blue;
  color: $gnf-white;
}

.gnf-cell__topic {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(85, 103, 127, 0.66);
  transition: color 0.55s $gnf-ease;
}

.gnf-cell:hover .gnf-cell__topic { color: $gnf-blue; }

.gnf-faq .gnf-cell__q {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  line-height: 1.34;
  letter-spacing: -0.02em;
  color: $gnf-navy;
  transition: color 0.55s $gnf-ease;
}

.gnf-cell:hover .gnf-cell__q { color: $gnf-blue-dk; }

.gnf-faq .gnf-cell__a {
  margin: 12px 0 0;
  padding: 0;
  font-size: 15.5px;
  font-weight: 400;
  line-height: 1.7;
  color: $gnf-body;
}

.gnf-faq a:focus-visible {
  outline: 2px solid $gnf-blue;
  outline-offset: 4px;
}


/* =========================================================
   MOTION
   Cells arrive along the reading order, so the block fills in
   left to right rather than all at once.
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gnfRise {
    from { opacity: 0; transform: translateY(18px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .gnf-faq .gnf-eyebrow,
  .gnf-faq .gnf-heading,
  .gnf-faq .gnf-sub,
  .gnf-headlink,
  .gnf-cell__body {
    animation: gnfRise 0.68s $gnf-ease backwards;
  }

  .gnf-faq .gnf-heading { animation-delay: 0.07s; }
  .gnf-faq .gnf-sub     { animation-delay: 0.14s; }
  .gnf-headlink         { animation-delay: 0.20s; }

  .gnf-cell--1 .gnf-cell__body { animation-delay: 0.26s; }
  .gnf-cell--2 .gnf-cell__body { animation-delay: 0.33s; }
  .gnf-cell--3 .gnf-cell__body { animation-delay: 0.40s; }
  .gnf-cell--4 .gnf-cell__body { animation-delay: 0.47s; }
  .gnf-cell--5 .gnf-cell__body { animation-delay: 0.54s; }
  .gnf-cell--6 .gnf-cell__body { animation-delay: 0.61s; }
}


/* =========================================================
   RESPONSIVE
   The dividers are rebuilt at each breakpoint, since which
   cell needs which rule depends on the column count.
   ========================================================= */

@media (max-width: 1024px) {

  .gnf-faq { padding: 84px 20px 92px; }

  .gnf-head {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
    margin-bottom: 34px;
  }

  .gnf-faq .gnf-heading { max-width: 620px; }
  .gnf-faq .gnf-sub { max-width: 600px; }

  .gnf-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }

  .gnf-cell { padding: 30px 26px 32px; }

  .gnf-cell--2,
  .gnf-cell--3,
  .gnf-cell--5,
  .gnf-cell--6 { border-left: 0; }

  .gnf-cell--2,
  .gnf-cell--4,
  .gnf-cell--6 { border-left: 1px solid $gnf-hair; }

  .gnf-cell--4,
  .gnf-cell--5,
  .gnf-cell--6 { border-top: 0; }

  .gnf-cell--3,
  .gnf-cell--4,
  .gnf-cell--5,
  .gnf-cell--6 { border-top: 1px solid $gnf-hair; }
}

@media (max-width: 620px) {

  .gnf-faq { padding: 62px 16px 70px; }

  .gnf-grid { grid-template-columns: minmax(0, 1fr); }

  .gnf-cell {
    padding: 26px 4px 28px;
    border-left: 0;
  }

  .gnf-cell--2,
  .gnf-cell--4,
  .gnf-cell--6 { border-left: 0; }

  .gnf-cell--2,
  .gnf-cell--3,
  .gnf-cell--4,
  .gnf-cell--5,
  .gnf-cell--6 { border-top: 1px solid $gnf-hair; }

  .gnf-faq .gnf-cell__q { font-size: 18px; }
  .gnf-faq .gnf-cell__a { font-size: 15px; }
  .gnf-faq .gnf-sub { font-size: 15.5px; padding-left: 18px; }
  .gnf-headlink { margin-left: 18px; }
}

@media (prefers-reduced-motion: reduce) {
  .gnf-faq * { transition: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW LANDING · FAQ
     Service Portal widget · Server script

     Copy lives here rather than in the template so every string
     passes through gs.getMessage and stays translatable. No
     table access, so no ACL considerations apply.

     Nothing is hidden behind a click, so each answer is kept to
     two or three short sentences and sits in its own cell. Anything program specific is pushed back to the
     program page on purpose, because it genuinely varies and a
     landing page should not pretend otherwise.

     Note on option names: every widget instance already has a
     built in "title" field, so options.title returns the
     instance title rather than anything you set. The heading
     option is named heading for that reason. The same applies
     to color, glyph and size.
     ========================================================= */

  function opt(name, fallback) {
    var value = options[name];
    if (value === null || value === undefined || value === '') {
      return fallback;
    }
    return value.toString();
  }

  data.regionLabel = opt('region_label', gs.getMessage('Frequently asked questions'));
  data.eyebrow     = opt('eyebrow', gs.getMessage('Questions'));
  data.heading     = opt('heading', gs.getMessage('The first call, in writing'));

  data.subhead = opt('subhead', gs.getMessage(
    'Six questions come up in almost every conversation before an application ' +
    'starts. Here they are answered, so you can skip the call if you would ' +
    'rather just get on with it.'));

  data.endLink = opt('end_link', gs.getMessage('Read the full process'));
  data.endUrl  = opt('end_url', '#how-applying-works');

  data.questions = [
    {
      index   : '01',
      topic   : gs.getMessage('Eligibility'),
      question: gs.getMessage('Do we need to be a registered charity?'),
      answer  : gs.getMessage(
        'Not always. Programs set their own eligibility, and some are open to ' +
        'constituted community groups, schools and councils as well as ' +
        'registered charities. The program page lists exactly who qualifies.')
    },
    {
      index   : '02',
      topic   : gs.getMessage('Eligibility'),
      question: gs.getMessage('Can we apply to more than one program?'),
      answer  : gs.getMessage(
        'Yes, and plenty of organisations do. Each application is assessed on ' +
        'its own merits, so a second one does not weaken the first.')
    },
    {
      index   : '03',
      topic   : gs.getMessage('Applying'),
      question: gs.getMessage('Do we have to finish it in one sitting?'),
      answer  : gs.getMessage(
        'No. It saves as you go, so you can start on Tuesday, chase the finance ' +
        'officer for a figure on Wednesday, and finish on Friday without losing ' +
        'a word.')
    },
    {
      index   : '04',
      topic   : gs.getMessage('Assessment'),
      question: gs.getMessage('When will we hear back?'),
      answer  : gs.getMessage(
        'That depends on the program, and each one publishes its own timeline. ' +
        'What does not vary is seeing the stage your application has reached, ' +
        'so the wait is a visible one rather than a silence you have to read ' +
        'something into.')
    },
    {
      index   : '05',
      topic   : gs.getMessage('Assessment'),
      question: gs.getMessage('We were declined last time. Worth trying again?'),
      answer  : gs.getMessage(
        'Usually yes. Declines come with the reason attached, and nothing ' +
        'carries into the next cycle. The same idea against the right program ' +
        'is a different application.')
    },
    {
      index   : '06',
      topic   : gs.getMessage('After the award'),
      question: gs.getMessage('What if the project changes once we have won?'),
      answer  : gs.getMessage(
        'Raise a change request and get it approved at the time. A change ' +
        'agreed in month four is administration. The same change found in the ' +
        'final report is a problem.')
    }
  ];

})();
